/**
 * Harness-side nudge carrier: a small Cursor hooks.json + script that drains
 * the durable Slack nudge store at tool boundaries (MCP / builtin tools).
 */
import { mkdir, readFile, rm, writeFile } from "node:fs/promises";
import { join } from "node:path";
import { isRecord } from "../../internal/is-record.js";
export const SLACK_NUDGE_ROOT_REL = ".agent-serve/slack-nudge-root";
export const SLACK_NUDGE_CONTINUATION_REL = ".agent-serve/slack-nudge-continuation";
export const SLACK_NUDGE_CARRIER_REL = ".agent-serve/slack-nudge-carrier.mjs";
/** Conversation allowed to claim nudges; subagents share the cwd and would otherwise take the parent's. */
export const SLACK_NUDGE_OWNER_REL = ".agent-serve/slack-nudge-owner";
/** Carrier script body — reads nudge-root + continuation, drains pending. */
export const SLACK_NUDGE_CARRIER_SCRIPT = `#!/usr/bin/env node
import { mkdir, readdir, readFile, rename, rm, writeFile } from "node:fs/promises";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const workspace = dirname(here);

function safeKey(value) {
  const trimmed = String(value ?? "").trim();
  if (trimmed === "" || trimmed === "." || trimmed === "..") return "_empty";
  const sanitized = trimmed
    .replace(/[^a-zA-Z0-9._-]+/g, "_")
    .replace(/^\\.+/, "")
    .replace(/\\.+/g, "_")
    .slice(0, 180);
  if (sanitized === "" || sanitized === "." || sanitized === "..") return "_empty";
  return sanitized;
}

async function readText(rel) {
  try {
    return (await readFile(join(workspace, rel), "utf8")).trim();
  } catch {
    return "";
  }
}

async function readStdin() {
  const chunks = [];
  const read = (async () => {
    for await (const chunk of process.stdin) chunks.push(chunk);
  })().catch(() => {});
  await Promise.race([
    read,
    new Promise((resolve) => setTimeout(resolve, 250).unref?.()),
  ]);
  process.stdin.destroy();
  return Buffer.concat(chunks).toString("utf8");
}

/** First caller pins ownership; a subagent cannot call a tool before its parent's Task call. */
async function ownsStore(caller) {
  if (caller === "") return true;
  const ownerPath = join(workspace, ${JSON.stringify(SLACK_NUDGE_OWNER_REL)});
  try {
    // wx is O_CREAT|O_EXCL, so creating the file is the claim: concurrent hooks cannot both win.
    await writeFile(ownerPath, caller + "\\n", { encoding: "utf8", flag: "wx" });
    return true;
  } catch (error) {
    if (error && error.code !== "EEXIST") return false;
  }
  // Claimed already — the only question left is whether we are the claimant.
  const owner = await readText(${JSON.stringify(SLACK_NUDGE_OWNER_REL)});
  return owner === "" || owner === caller;
}

async function main() {
  const raw = await readStdin();
  let caller = "";
  try {
    const parsed = JSON.parse(raw);
    if (parsed && typeof parsed.conversation_id === "string") {
      caller = parsed.conversation_id.trim();
    }
  } catch {
    // Fail open: an unparseable payload must not strand the follow-up.
  }
  const root = await readText(${JSON.stringify(SLACK_NUDGE_ROOT_REL)});
  const continuation = await readText(
    ${JSON.stringify(SLACK_NUDGE_CONTINUATION_REL)}
  );
  if (root === "" || continuation === "") {
    process.stdout.write("{}\\n");
    return;
  }
  // Not ours: leave it pending for the parent or the turn-boundary drain.
  if (!(await ownsStore(caller))) {
    process.stdout.write("{}\\n");
    return;
  }
  const pendingDir = join(root, safeKey(continuation), "pending");
  const deliveredDir = join(root, safeKey(continuation), "delivered");
  let names = [];
  try {
    names = await readdir(pendingDir);
  } catch {
    process.stdout.write("{}\\n");
    return;
  }
  const nudges = [];
  await mkdir(deliveredDir, { recursive: true });
  for (const name of names) {
    if (!name.endsWith(".json")) continue;
    const pendingPath = join(pendingDir, name);
    let record;
    try {
      record = JSON.parse(await readFile(pendingPath, "utf8"));
    } catch {
      continue;
    }
    const sourceTs = typeof record.sourceTs === "string" ? record.sourceTs : "";
    if (sourceTs === "") continue;
    const dest = join(deliveredDir, safeKey(sourceTs));
    try {
      await readFile(dest, "utf8");
      await rm(pendingPath, { force: true });
      continue;
    } catch {
      // not delivered yet
    }
    const tmp = dest + "." + process.pid + ".tmp";
    try {
      await writeFile(tmp, JSON.stringify(record) + "\\n", "utf8");
      await rename(tmp, dest);
      await rm(pendingPath, { force: true });
      nudges.push(record);
    } catch {
      await rm(tmp, { force: true }).catch(() => {});
      await rm(pendingPath, { force: true }).catch(() => {});
    }
  }
  if (nudges.length === 0) {
    process.stdout.write("{}\\n");
    return;
  }
  const lines = [
    "<slack_followup>",
    "New Slack follow-up(s) arrived while you were working. Incorporate them before your final reply. If an ask was already answered in-thread, ack briefly instead of re-answering.",
    "",
  ];
  for (const nudge of nudges) {
    const who =
      typeof nudge.author === "string" && nudge.author !== ""
        ? nudge.author
        : "someone";
    lines.push("- " + who + " @ " + nudge.sourceTs + ":");
    lines.push(
      typeof nudge.text === "string" && nudge.text.trim() !== ""
        ? nudge.text.trim()
        : "(empty)"
    );
    lines.push("");
  }
  lines.push("</slack_followup>");
  process.stdout.write(
    JSON.stringify({ additional_context: lines.join("\\n").trimEnd() }) + "\\n"
  );
}

main().catch(() => {
  process.stdout.write("{}\\n");
});
`;
function isHookEntry(value) {
    return (isRecord(value) &&
        typeof value.command === "string" &&
        (value.failClosed === undefined || typeof value.failClosed === "boolean"));
}
/** Keep entries this carrier can read. A bad list does not drop the rest of the file. */
function readHooksConfig(value) {
    if (!isRecord(value)) {
        return { version: 1, hooks: {} };
    }
    const hooks = {};
    if (isRecord(value.hooks)) {
        for (const [step, list] of Object.entries(value.hooks)) {
            if (!Array.isArray(list)) {
                continue;
            }
            hooks[step] = list.filter(isHookEntry);
        }
    }
    return {
        version: typeof value.version === "number" ? value.version : 1,
        hooks,
    };
}
/**
 * Write carrier script + pointer files and ensure pre/postToolUse hooks invoke it.
 * Safe to call every turn (idempotent overwrite of carrier + pointers).
 */
export async function materializeSlackNudgeCarrier(args) {
    if (args.continuationKey.trim() === "") {
        return;
    }
    await mkdir(join(args.harnessCwd, ".agent-serve"), { recursive: true });
    await mkdir(join(args.harnessCwd, ".cursor"), { recursive: true });
    await writeFile(join(args.harnessCwd, SLACK_NUDGE_ROOT_REL), `${args.nudgeRootDir}\n`, "utf8");
    await writeFile(join(args.harnessCwd, SLACK_NUDGE_CONTINUATION_REL), `${args.continuationKey}\n`, "utf8");
    await writeFile(join(args.harnessCwd, SLACK_NUDGE_CARRIER_REL), SLACK_NUDGE_CARRIER_SCRIPT, "utf8");
    await rm(join(args.harnessCwd, SLACK_NUDGE_OWNER_REL), { force: true });
    const hooksPath = join(args.harnessCwd, ".cursor", "hooks.json");
    let existing = { version: 1, hooks: {} };
    try {
        const parsed = JSON.parse(await readFile(hooksPath, "utf8"));
        existing = readHooksConfig(parsed);
    }
    catch {
        // fresh
    }
    const hooks = { ...(existing.hooks ?? {}) };
    const command = `node ${SLACK_NUDGE_CARRIER_REL}`;
    for (const step of ["preToolUse", "postToolUse"]) {
        const list = [...(hooks[step] ?? [])].filter((entry) => !entry.command.includes("slack-nudge-carrier"));
        list.push({ command, failClosed: false });
        hooks[step] = list;
    }
    const next = {
        version: existing.version ?? 1,
        hooks,
    };
    await writeFile(hooksPath, `${JSON.stringify(next, null, 2)}\n`, "utf8");
}
